    Given the user is a Requester
    And the user accesses the V2 component
    When the user attempts to re-assign a request
    Then the user should not be able to re-assign the request
    And the system should only allow Workflow or Main Admins to re-assign

Python:
from behave import given, when, then

@given('the user is a Requester')
def step_given_user_is_requester(context):
    context.user_role = 'Requester'

@given('the user accesses the V2 component')
def step_given_user_accesses_v2_component(context):
    context.component_version = 'V2'

@when('the user attempts to re-assign a request')
def step_when_user_attempts_reassign(context):
    context.attempt_reassign = True

@then('the user should not be able to re-assign the request')
def step_then_user_cannot_reassign(context):
    assert not context.user_role == 'Workflow Admin' and not context.user_role == 'Main Admin'

@then('the system should only allow Workflow or Main Admins to re-assign')
def step_then_only_admins_can_reassign(context):
    assert context.user_role in ['Workflow Admin', 'Main Admin']

