def step_given_user_opens_editor(context):
    context.editor_mode = 'Adopter'
    context.allowed_layers = ['Layer1', 'Layer2']
    context.restricted_layers = ['Layer3', 'Layer4']

@when('the user attempts to edit a layer allowed by the Template Creator')
def step_when_user_edits_allowed_layer(context):
    context.layer_to_edit = 'Layer1'
    context.edit_successful = context.layer_to_edit in context.allowed_layers

