def step_then_user_can_edit_layer(context):
    assert context.edit_successful is True

@then('the user cannot edit layers not allowed by the Template Creator')
def step_then_user_cannot_edit_restricted_layers(context):
    for layer in context.restricted_layers:
        assert layer not in context.allowed_layers

