def step_given_record_with_status(context, status):
    context.record_status = status

@when('the user views the record')
def step_when_user_views_record(context):
    context.viewed_status = context.record_status

@then('the header displays the status "{expected_status}"')
def step_then_header_displays_status(context, expected_status):
    assert context.viewed_status == expected_status, f"Expected {expected_status}, but got {context.viewed_status}"

