Gherkin:
Feature: Display loading indicator while fetching and building results

  Scenario: User sees loading wheel on 'Ask' button while results are loading
    Given the user has entered a query
    When the user clicks the 'Ask' button
    Then a loading wheel appears on the 'Ask' button
    And the loading wheel remains visible while the answer is being fetched and built
    And the loading wheel disappears when the answer is fully built

Python:
from behave import given, when, then

@given('the user has entered a query')
def step_given_user_has_entered_query(context):
    context.query = "example query"

@when('the user clicks the \'Ask\' button')
def step_when_user_clicks_ask_button(context):
    context.button_clicked = True

@then('a loading wheel appears on the \'Ask\' button')
def step_then_loading_wheel_appears(context):
    assert context.button_clicked
    context.loading_wheel_visible = True

@then('the loading wheel remains visible while the answer is being fetched and built')
def step_then_loading_wheel_remains_visible(context):
    assert context.loading_wheel_visible

@then('the loading wheel disappears when the answer is fully built')
def step_then_loading_wheel_disappears(context):
    context.loading_wheel_visible = False
    assert not context.loading_wheel_visible

