Gherkin:
Feature: Publish approval process for parent and child records

  Scenario: Child records are created when parent record is approved
    Given a parent record is submitted for approval
    And the parent record is pending approval
    When the parent record status becomes "Approved"
    Then child records are created
    And the creator of the child records is the creator of the parent record

Python:
from behave import given, when, then

@given('a parent record is submitted for approval')
def step_given_parent_record_submitted(context):
    context.parent_record = submit_parent_record_for_approval()

@given('the parent record is pending approval')
def step_given_parent_record_pending(context):
    assert context.parent_record.status == 'Pending Approval'

@when('the parent record status becomes "Approved"')
def step_when_parent_record_approved(context):
    context.parent_record.status = 'Approved'
    approve_parent_record(context.parent_record)

@then('child records are created')
def step_then_child_records_created(context):
    context.child_records = create_child_records(context.parent_record)
    assert context.child_records is not None

@then('the creator of the child records is the creator of the parent record')
def step_then_creator_of_child_records(context):
    for child_record in context.child_records:
        assert child_record.creator == context.parent_record.creator
